entries[27580] = { ["name"] = "Tödlicher Stoß", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nWaffen ( Hotfix - Passivfähigkeit )\nEin heimtückischer Stoß, der Waffenschaden plus 160 verursacht und das Ziel verwundet, sodass die Wirksamkeit jeglicher Heilung 10 Sek. lang um 50% verringert wird.\n\nFuror, Schutz\nEin heimtückischer Stoß, der Waffenschaden plus 160 verursacht und das Ziel verwundet, sodass die Wirksamkeit jeglicher Heilung 10 Sek. lang um 50% verringert wird." }
