entries[27664] = { ["name"] = "Geschenk der Freundschaft von Sturmwind", ["text"] = "Sofort\nReagenzien:\nKartenbündel , Brotsack mit hausgemachtem Brot , Pfandsammlung von Sturmwind\nRechtsklicken, um aus einem Kartenbündel, einem Brotsack mit hausgemachtem Brot und einer Pfandsammlung von Sturmwind eine Geschenkesammlung von Sturmwind herzustellen." }
