entries[27807] = { ["name"] = "Gallenlache", ["text"] = "20 Meter Reichweite\nSofort\nFügt jedem Feind in einem kegelförmigen Bereich vor dem Zaubernden 1200 Naturschaden und zusätzlich alle 3 Sek. 4375 bis 5625 Schaden zu. Naturwiderstand um 1200 verringert. Hält 15 Sek. lang an." }
