entries[27827] = { ["name"] = "Geist der Erlösung", ["text"] = "Sofort\nBei seinem Tod verwandelt sich der Priester 15 Sek. lang in einen Geist der Erlösung. Der Geist kann sich weder bewegen oder angreifen, noch kann er das Ziel von Zaubern oder Effekten sein. In dieser Gestalt kann der Priester jeglichen Heilzauber ohne irgendwelche Kosten wirken. Nach Ablauf der Verwandlung stirbt der Priester." }
entries[27829] = { ["name"] = "Gamaschen der Titanen", ["text"] = "Wirken in 15 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (12), Verzauberter Thoriumbarren (20), Essenz der Erde (10), Fläschchen der Titanen (2)\nGamaschen der Titanen\nWird beim Anlegen gebunden\nBeine Platte\n653 Rüstung\n+30 Stärke\nErhöht Eure Trefferwertung um + 20.\nErhöht Eure kritische Trefferwertung um + 14.\nHaltbarkeit 120 / 120\n55" }
entries[27830] = { ["name"] = "Willensbrecher", ["text"] = "Wirken in 15 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (15), Dunkeleisenbarren (10), Essenz des Untodes (20), Dunkelrune (20), Teufelssaurierleder (10)\nWillensbrecher\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n86 - 161 Schaden Tempo 2.70\n(45.74 Schaden pro Sekunde)\nErhöht Eure Trefferwertung um + 10.\nErhöht Eure kritische Trefferwertung um + 14.\nHaltbarkeit 110 / 110\n58" }
entries[27831] = { ["name"] = "Schattenblitzsalve", ["text"] = "Wirken in 1.5 sek.\nSchleudert Geschosse von dunkler Magie auf in der Nähe befindliche Feinde und verursacht Schattenschaden." }
entries[27832] = { ["name"] = "Weisenklinge", ["text"] = "Wirken in 15 sek.\nTools: Schmiedehammer\nReagenzien:\nArkanitbarren (12), Nexuskristall (2), Fläschchen der obersten Macht (2), Verzaubertes Leder (4)\nWeisenklinge\nWird beim Anlegen gebunden\nEinhändig Schwert\n29 - 54 Schaden Tempo 1.80\n(23.06 Schaden pro Sekunde)\n+17 Ausdauer\nErhöht Eure Trefferwertung um + 10.\nErhöht die Zaubermacht um + 141.\nHaltbarkeit 110 / 110\n59" }
