entries[28271] = { ["name"] = "Verwandlung", ["text"] = "2% von Grundmana 30 Meter Reichweite\nWirken in 1.7 sek.\nVerwandelt den Feind in eine harmlose Schildkröte und zwingt ihn, 50 Sek. lang so herumzuwandern. Während der Gegner in eine Schildkröte verwandelt ist, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden wandelt ihn in seine normale Gestalt zurück.\n\nEs kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[28272] = { ["name"] = "Verwandlung", ["text"] = "2% von Grundmana 30 Meter Reichweite\nWirken in 1.7 sek.\nVerwandelt den Feind in ein harmloses Schwein und zwingt ihn, 50 Sek. lang so herumzuwandern. Während der Gegner in ein Schwein verwandelt ist, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden wandelt ihn in seine normale Gestalt zurück.\n\nEs kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
